ATTACH ':memory:' AS db2; CREATE TABLE db2.t2(x,y); INSERT INTO db2.t2 VALUES(11,'x'),(12,'y'); CREATE TABLE db2.tx(x1,x2,y1,y2); INSERT INTO db2.tx VALUES(1,11,'x','x'),(2,12,'y','y'); CREATE TRIGGER db2.r1 AFTER UPDATE ON t2 FOR EACH ROW BEGIN INSERT INTO tx VALUES(OLD.x,NEW.x,OLD.y,NEW.y); END; UPDATE db2.t2 SET x=x+10; INSERT INTO main.capture SELECT x1,x2,y1,y2 FROM db2.tx ORDER BY rowid;